contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint depositAmount, uint collectAmount, address logAddr) public payable {
        require(address(this).balance >= depositAmount);

        // Set up LogFile and MinSum before Initialized
        c.SetLogFile(logAddr);
        c.SetMinSum(0);
        c.Initialized();

        // Deposit some funds
        c.Deposit{value: depositAmount}();

        // Read log history length before Collect
        LogFile log = LogFile(logAddr);
        uint historyBefore = log.History.length;

        // Try to Collect
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // If Collect succeeded, History length must have increased by exactly 1
        if (!reverted) {
            uint historyAfter = log.History.length;
            assert(historyAfter == historyBefore + 1);
        } else {
            // For a revert, no new message is added; assert that length is unchanged
            uint historyAfter = log.History.length;
            assert(historyAfter == historyBefore);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint depositAmount, uint collectAmount, address logAddr) public payable {
        require(address(this).balance >= depositAmount);

        // Set up LogFile and MinSum before Initialized
        c.SetLogFile(logAddr);
        c.SetMinSum(0);
        c.Initialized();

        // Deposit some funds so the test contract has a balance in C
        c.Deposit{value: depositAmount}();

        LogFile log = LogFile(logAddr);

        // Read the initial message-count by probing the public History getter.
        // The getter has signature History(uint256) and reverts when the index is out of bounds,
        // so we can count messages by probing successive indices.
        uint msgCountBefore = 0;
        while (true) {
            try log.History(msgCountBefore) returns (address, string memory, uint, uint) {
                msgCountBefore++;
            } catch {
                break;
            }
        }

        // Try to Collect
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Count messages after Collect
        uint msgCountAfter = 0;
        while (true) {
            try log.History(msgCountAfter) returns (address, string memory, uint, uint) {
                msgCountAfter++;
            } catch {
                break;
            }
        }

        // Property: a successful Collect always appends exactly one message;
        // a failed Collect appends none.
        assert(!reverted ? msgCountAfter == msgCountBefore + 1 : msgCountAfter == msgCountBefore);
    }

    receive() external payable {}
}

